package at.pinzker.taskloop;
import android.app.*;import android.content.*;import android.os.*;import android.media.*;
public final class Scheduler {
 public static final String CHANNEL="taskloop_alarm_v3",NORMAL="taskloop_notification_v1";
 public static void channel(Context c){NotificationManager n=c.getSystemService(NotificationManager.class);NotificationChannel alarm=new NotificationChannel(CHANNEL,L.english(c)?"Task alarms":"Aufgaben-Alarme",NotificationManager.IMPORTANCE_HIGH);alarm.setSound(null,null);alarm.enableVibration(false);alarm.setLockscreenVisibility(Notification.VISIBILITY_PRIVATE);n.createNotificationChannel(alarm);NotificationChannel normal=new NotificationChannel(NORMAL,L.english(c)?"Task notifications":"Aufgaben-Benachrichtigungen",NotificationManager.IMPORTANCE_DEFAULT);n.createNotificationChannel(normal);}
 public static boolean exact(Context c){return Build.VERSION.SDK_INT<31||c.getSystemService(AlarmManager.class).canScheduleExactAlarms();}
 static PendingIntent alarm(Context c,int id){return PendingIntent.getBroadcast(c,id,new Intent(c,AlarmReceiver.class).setAction("FIRE").putExtra("id",id),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 public static void schedule(Context c,Task t){if(!t.active||!t.reminder||t.next<=0||!ReminderPauses.isEnabled(c,t.category)){cancel(c,t.id);ReminderPauses.scheduleResume(c);return;}AlarmManager a=c.getSystemService(AlarmManager.class);long at=Math.max(System.currentTimeMillis()+1000,t.next);try{if(exact(c)){PendingIntent show=PendingIntent.getActivity(c,t.id,new Intent(c,MainActivity.class).putExtra("edit",t.id),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);a.setAlarmClock(new AlarmManager.AlarmClockInfo(at,show),alarm(c,t.id));}else a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,alarm(c,t.id));}catch(SecurityException e){Store.log(c,"Alarmberechtigung fehlt: #"+t.id);a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,alarm(c,t.id));}}
 public static void cancel(Context c,int id){c.getSystemService(AlarmManager.class).cancel(alarm(c,id));}
 public static void clearNotification(Context c,int id){AlarmSoundService.stop(c,id);c.getSystemService(NotificationManager.class).cancel(id);c.sendBroadcast(new Intent(c.getPackageName()+".CLOSE").setPackage(c.getPackageName()).putExtra("id",id));}
 static PendingIntent action(Context c,int id,String action){return PendingIntent.getBroadcast(c,id,new Intent(c,AlarmReceiver.class).setAction(action).putExtra("id",id),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 public static void display(Context c,Task t){channel(c);boolean normal=t.alarmMode==AlarmRules.NOTIFICATION;NotificationManager n=c.getSystemService(NotificationManager.class);Intent i=normal?new Intent(c,MainActivity.class).putExtra("edit",t.id):new Intent(c,AlarmActivity.class).putExtra("id",t.id);i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);ActivityOptions opts=ActivityOptions.makeBasic();if(Build.VERSION.SDK_INT>=35)opts.setPendingIntentCreatorBackgroundActivityStartMode(ActivityOptions.MODE_BACKGROUND_ACTIVITY_START_ALLOWED);PendingIntent content=PendingIntent.getActivity(c,t.id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE,opts.toBundle());Notification.Builder b=new Notification.Builder(c,normal?NORMAL:CHANNEL).setSmallIcon(R.drawable.ic_notify).setContentTitle(t.title).setContentText(t.rhythm(c)).setStyle(new Notification.BigTextStyle().bigText(t.title+(!t.note.isEmpty()?"\n"+t.note:""))).setCategory(normal?Notification.CATEGORY_REMINDER:Notification.CATEGORY_ALARM).setVisibility(Notification.VISIBILITY_PRIVATE).setColor(Design.INK).setContentIntent(content).setAutoCancel(normal).setOngoing(!normal).setOnlyAlertOnce(false).addAction(new Notification.Action.Builder(null,L.english(c)?"Complete":"erledigt",action(c,t.id,"DONE")).build()).addAction(new Notification.Action.Builder(null,L.english(c)?"Snooze":"Später",action(c,t.id,"SNOOZE")).build()).addAction(new Notification.Action.Builder(null,L.english(c)?"Finish task":"Endgültig erledigen",action(c,t.id,"FINISH")).build());if(!normal&&(Build.VERSION.SDK_INT<34||n.canUseFullScreenIntent()))b.setFullScreenIntent(content,true);try{n.notify(t.id,b.build());Store.log(c,L.english(c)?"Reminder shown: #"+t.id:"Erinnerung ausgegeben: #"+t.id);if(!normal&&(Store.prefs(c).getBoolean("sound_enabled",false)||Store.prefs(c).getBoolean("alarm_vibrate",false)))try{AlarmSoundService.start(c,t.id);}catch(RuntimeException e){Store.log(c,"Alarm sound service blocked: #"+t.id+" "+e.getClass().getSimpleName());}}catch(SecurityException e){Store.log(c,"Benachrichtigungsberechtigung fehlt: #"+t.id);}}
 public static void done(Context c,Task t){long now=System.currentTimeMillis();if(!t.reminder||t.doneMode==1||t.kind==0){finish(c,t);return;}t.next=t.regular(now);t.active=t.next>0;t.completedAt=t.active?0:now;t.last=0;clearNotification(c,t.id);Store.save(c,t);schedule(c,t);Store.log(c,L.english(c)?"Occurrence completed: #"+t.id:"Termin erledigt: #"+t.id);}
 public static void finish(Context c,Task t){t.active=false;t.next=0;t.last=0;t.completedAt=System.currentTimeMillis();cancel(c,t.id);clearNotification(c,t.id);Store.save(c,t);Store.log(c,L.english(c)?"Task completed: #"+t.id:"Aufgabe endgültig erledigt: #"+t.id);}
 public static void skip(Context c,Task t){if(t.kind==0)return;t.next=t.regular(System.currentTimeMillis());t.last=0;clearNotification(c,t.id);Store.save(c,t);schedule(c,t);Store.log(c,L.english(c)?"Occurrence skipped: #"+t.id:"Termin übersprungen: #"+t.id);}
 public static void snooze(Context c,Task t){snooze(c,t,t.pause);}
 public static void snooze(Context c,Task t,int minutes){t.next=System.currentTimeMillis()+Math.max(1,Math.min(10080,minutes))*60000L;t.active=true;t.last=0;clearNotification(c,t.id);Store.save(c,t);schedule(c,t);Store.log(c,L.english(c)?"Snoozed: #"+t.id:"Verlängert: #"+t.id);}
 public static void restore(Context c){ReminderPauses.expire(c);ReminderPauses.scheduleResume(c);for(Task t:Store.all(c))if(t.active&&t.next>0)schedule(c,t);}
}
